def slug(x):return re.sub(r'[^a-z0-9]+','-',x.lower()).strip('-')
def validate_svg(name,scene):
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">{scene}</svg>'
 ET.fromstring(svg)
 assert not re.search(r'<(?:script|image|text|foreignObject)|href=|onload=',svg,re.I),name
 return svg

def main():
 cand=json.load(open(R/'shared/v63-candidates.json'))
 assert set(n for n,_,_ in cand)==set(S),set(n for n,_,_ in cand)^set(S)
 old=json.load(open(R/'shared/v61-art-manifest.json'))['icons']
 generic={x['name']:x for x in old if x['art_mode']=='motif-composite'}
 assert set(L).issubset(generic)
 # Export current V62 catalog; no silent alterations of base pair rules
 base=json.loads(subprocess.check_output(['node','tools/export-v61-base.mjs'],cwd=R))
 for version in [61,62]:
  m=(R/f'client/src/organic-pack-v{version}.js').read_text()
  pack=json.loads(m.split(' = ',1)[1].rstrip(' ;\n'))
  base['items']+=pack['items'];base['recipes'].update({'|'.join(sorted([a,b])):c for a,b,c in pack['recipes']})
 norm=lambda a:unicodedata.normalize('NFKD',a).casefold().strip()
 lookup={norm(x['name']):x['id'] for x in base['items']}
 used=set(base['recipes']);packs=[];recs=[];newart={};redraw={};manifest=[];redraw_manifest=[]
 assets=R/'client/assets/v63';(assets/'new').mkdir(parents=True,exist_ok=True);(assets/'redrawn-v61').mkdir(parents=True,exist_ok=True)
 for name,a,b in cand:
  assert norm(name) not in lookup,name
  assert norm(a) in lookup and norm(b) in lookup,(name,a,b)
  key='|'.join(sorted([lookup[norm(a)],lookup[norm(b)]]));assert key not in used,(name,a,b)
  id='organic63:'+slug(name)
  used.add(key); packs.append(dict(id=id,name=name,category=('life' if any(x in name for x in ['Crab','Jellyfish','Moth','Salamander','Edelweiss','Baobab']) else 'technology' if any(x in name for x in ['Keyboard','Spyglass','Projector','Slide','Wheel','Whisk','Dipper']) else 'culture' if any(x in name for x in ['Origami','Lantern','Model','Snow Globe']) else 'material'),summary=f'{name}, crafted from {a.lower()} and {b.lower()}.',iconFamily='organic'))
  recs.append([lookup[norm(a)],lookup[norm(b)],id])
  art=validate_svg(name,S[name]); p=assets/'new'/(slug(name)+'.svg');p.write_text(art)
  newart[name.lower()]=art
  manifest.append(dict(name=name,id=id,path=str(p.relative_to(R)),ingredients=[a,b],sha256=hashlib.sha256(art.encode()).hexdigest(),art_mode='bespoke-silhouette'))
 for name,scene in L.items():
  art=validate_svg(name,scene);p=assets/'redrawn-v61'/(slug(name)+'.svg');p.write_text(art)
  redraw[name.lower()]=art
  redraw_manifest.append(dict(name=name,id=generic[name]['id'],path=str(p.relative_to(R)),sha256=hashlib.sha256(art.encode()).hexdigest(),previous_art_mode='motif-composite',art_mode='bespoke-silhouette'))
 (R/'client/src/organic-pack-v63.js').write_text('/* V63: curated global recipes, never runtime-generated */\nexport const ORGANIC_V63 = '+json.dumps(dict(items=packs,recipes=recs),ensure_ascii=False,separators=(',',':'))+';\n')
 (R/'client/src/organic-art-v63.js').write_text('/* V63: new bespoke SVGs and audited overrides for V61 composite art */\nexport const ORGANIC_ART_V63 = '+json.dumps({**newart,**redraw},separators=(',',':'))+';\n')
 (R/'shared/v63-approved.json').write_text(json.dumps({'version':63,'new_items':manifest,'redrawn_v61':redraw_manifest},indent=2)+'\n')
 print('V63:',len(packs),'new elements',len(recs),'recipes',len(redraw),'redrawn legacy V61 icons')
if __name__=='__main__':main()
